import{_ as e,o as r,c as a,a4 as d}from"./chunks/framework.BybBnFXO.js";const m=JSON.parse('{"title":"Oxides","description":"","frontmatter":{"title":"Oxides","mineralGroup":"oxides"},"headers":[],"relativePath":"mineral-groups/oxides.md","filePath":"mineral-groups/oxides.md","lastUpdated":1785920831000}'),i={name:"mineral-groups/oxides.md"};function o(s,t,l,n,u,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="oxides" tabindex="-1">Oxides <a class="header-anchor" href="#oxides" aria-label="Permalink to &quot;Oxides&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Oxides form one of the most important gem families, including corundum (ruby, sapphire), spinel, rutile, and diaspore. Coloring elements are predominantly transition metals (Cr, Fe, Ti, V). Strong ionic + covalent bonding makes oxides hard (Mohs 7–9) and durable for everyday wear.</p><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>M₂O₃ / MO₂ / MO</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>Oxide (O²⁻) anions form hexagonal close-packed or cubic close-packed frameworks; metal cations occupy octahedral or tetrahedral interstices. Corundum subgroup: trigonal; spinel subgroup: cubic.</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Ruby / 红宝石</td><td>Al₂O₃ + Cr</td><td>corundum</td></tr><tr><td>Sapphire (blue) / 蓝宝石</td><td>Al₂O₃ + Fe,Ti</td><td>corundum</td></tr><tr><td>Yellow Sapphire / 黄宝石</td><td>Al₂O₃ + Fe</td><td>corundum</td></tr><tr><td>Padparadscha / 帕帕拉恰</td><td>Al₂O₃ + Cr,Fe</td><td>corundum</td></tr><tr><td>Spinel / 尖晶石</td><td>MgAl₂O₄</td><td>spinel</td></tr><tr><td>Hematite / 赤铁矿</td><td>Fe₂O₃</td><td>hematite</td></tr><tr><td>Rutile / 金红石</td><td>TiO₂</td><td>rutile</td></tr><tr><td>Diaspore / 水铝石</td><td>AlO(OH)</td><td>boehmite</td></tr><tr><td>Cassiterite / 锡石</td><td>SnO₂</td><td>rutile</td></tr><tr><td>Spinel (cobalt-blue) / 钴蓝尖晶石</td><td>CoAl₂O₄</td><td>spinel</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p>',10)])])}const h=e(i,[["render",o]]);export{m as __pageData,h as default};
